const form=document.getElementById("tileForm"),result=document.getElementById("result");form&&form.addEventListener("submit",t=>{t.preventDefault();const l=parseFloat(document.getElementById("length").value)||0,i=parseFloat(document.getElementById("width").value)||0,e=parseFloat(document.getElementById("tw").value)||0,s=parseFloat(document.getElementById("th").value)||0,o=parseFloat(document.getElementById("reserve").value)||0,a=parseInt(document.getElementById("perBox").value,10)||0;if(l<=0||i<=0||e<=0||s<=0){result.innerHTML='<p style="margin:0;color:#c0392b">Введите длину и ширину поверхности и размеры плитки больше нуля.</p>';return}const c=l*i,p=e/100*(s/100),n=Math.ceil(c*(1+o/100)/p),r=a>0?Math.ceil(n/a):null;result.innerHTML=`
      <div class="result-list">
        <div class="item"><span>Площадь поверхности</span><span class="val">${fmt(c)} м²</span></div>
        <div class="item"><span>Плитка</span><span class="val">${e} × ${s} см</span></div>
        <div class="item"><span>Плиток (с запасом ${fmt(o)}%)</span><span class="val">${fmt(n)} шт</span></div>
        ${r?`<div class="item total"><span>Упаковок (по ${a} шт)</span><span class="val">${fmt(r)} уп.</span></div>`:`<div class="item total"><span>Итого</span><span class="val">${fmt(n)} шт</span></div>`}
      </div>
      <p class="hint" style="margin-top:14px">Площадь одной плитки: ${fmt(p)} м².</p>
    `});function fmt(t){return new Intl.NumberFormat("ru-RU",{maximumFractionDigits:2}).format(t)}
